const fs=require('fs'),p=require('path'),cr=require('crypto');const root='Z:/00.Roboti/EVA.Pro/Eva-contab/Audit_P01_2026-11-01',ex=p.join(root,'executie'),src='D:/CodexWork/eva-audit-p01-readonly-20261102',repo='6df998aee0e514d30856c461962afe99ebd0d113',hash=b=>cr.createHash('sha256').update(b).digest('hex'),load=f=>JSON.parse(fs.readFileSync(f,'utf8').replace(/"'^'"\\uFEFF/,'')),plan=load(root+'/A10_plan.json'),ar=load(root+'/A11_verdict_arbitraj.json'),approved=load(root+'/A11_verdict_plan.json'),cov=load(ex+'/A10/coverage.json'),short=i=>'A10-CK-'+String(i).padStart(2,'0');const sources={VERS:['A10/runtime_versions.json','SSH direct read-only: comparație amprentă pe 5 cabinete și 2 JAR din Git.','5 cabinete; nu stabilește execuția fiecărui simbol.'],QUEUE:['A10/queue_probe.json','Probe directe asupra scripturilor din SHA pinuit în cozi, jurnale și sloturi sintetice.', 'Fără modificări ale cozii reale.'],RUN:['A10/runtime_probe.json','HTTP ASGI, DB SQLite local, două taburi tranzacționale, canari, injecție post-efect prin stub.','ERP și identitatea sunt simulate conform condițiilor înregistrate.'],RESTORE:['A10/restore_probe.json','PG16 sintetic fără rețea, dump și restore în baze separate plus arhivă anexă: slot, permis, timpi și cleanup.','Schemă martor și fișier sintetic, nu backup integral ERP sau site.'],LOAD:['A10/load_probe.json','Flask in-process pe două canale, 1k/10k produse, 1/10/30 concurență, 600 cereri măsurate, 120 warmup, paginare invalidă.', 'Măsurare locală fără CDN/DB nativ; prag intern nu este SLA de producție.'],GUARDS:['A10/guards_probe.json','Trei harness-uri hermetice din commit executate cu programa de test/fixture.','Build Maven real, OSGi și deploy nu sunt exercițiul acestor teste.'],COVER:['A10/coverage.json','Verificare integrală de hash pentru sursele titularului și filtrarea suitei; trasabilitate la C15.','Amprenta/citirea automată nu echivalează cu analiza semantică a fiecărei linii.'],BUNDLE:['Diferente_bundle_CESIRO.json','Reutilizare probă transversală: fișiere de clasă comparate binar pe CESIRO.','Delta între ediții nu este singură o eroare de implementare.'],WEB:['Provenienta_API_web.json','Fișiere comparate între Git și servicii runtime.','Eșantion materializat, nu stabilește identitate completă a întregii imagini.'],NATIVE:['Matrice_nativa_reutilizare.json','Matrice de proveniență r13, surse și JAR native.','Limitele rubricii native sunt moștenite.'],A05:['A05_raport.json','Fixture independent A05 fresh seed/activation, în special A05-F09 și A05-F10.','Constatare a zonei A05, citată pentru readiness.'],A08:['A08_raport.json','Probe storefront A08 (în special F07, F08).','Distincte de benchmarkul A10; proveniență proprie.'],A01:['A01_raport.json','Probe API/izolare separate A01.','Nu extind verificarea la rute care n-au fost testate.'],LEASE:['Ciclu_viata_slot_test.json','Stare și jurnal al sesiunii/permisului, dispariție PG și rerulare HR.','Defect de infrastructură reprodus în scenariul nume/TTY.'],SUITE:['BE-suite/inregistrat.json','Suită înregistrată 1446 PASS, 3 eșecuri și 51 omise; cazurile relevante individualizate în coverage.','Raportul inițial nu înlocuiește reluările țintite.'],HR:['BE-suite/hr_fixture_final.json','Reluare a celor trei probe HR cu permis corect.','Rezultat de comparație pentru infrastructură.'],CHANNELS:['Canale_instalate.json','30 înregistrări configurate de site și observații de servicii.','Inventar la data probei.']};
const evidence=Object.fromEntries(Object.entries(sources).map(([id,[file,observed_result,limitations]])=>{const full=p.join(ex,file),buf=fs.readFileSync(full),v=JSON.parse(buf.toString().replace(/"'^'"\\uFEFF/,''));return[id,{evidence_id:id,raw_artifact_path:'executie/'+file,sha256:hash(buf),kind:id==='COVER'?'inventar':file.startsWith('A10/')?'probă directă A10':'probă transversală identificată',observed_result,limitations,executor:file.startsWith('A10/')?'A10':'autor indicat în proba transversală',environment:limitations,captured_at_utc:v.utc||v.captured_utc||v.captured||v.observed_utc||v.created_utc||null,version_or_sha:repo,command_or_steps:file.startsWith('A10/')&&file"'!=='"'A10/coverage.json'?('Vezi '+file.replace('.json',file.includes('runtime_probe')||file.includes('load_probe')?'.py':'.sh')):'Vezi proveniența și limitările din artefact.'}]}));
const findings=[[\"F01\",\"P1\",\"Cele două unelte de coadă acceptă o cale în loc de ID de slot\",\"QUEUE\",\"8 9\",\"În ambele unelte, elibereaza ../marker returnează rc0 și șterge markerul sintetic din directorul părinte.\",\"tools/status/coada_builduri.sh:74 tools/status/coada_montari.sh:77\",\"Operator cu acces la utilitar și drept de scriere în directorul țintă.\",\"Permite ștergerea unor fișiere la care contul local are deja acces, inclusiv din alt task.\",\"Validează gramatica ID-ului de slot și apartenența lui în registru. Rezolvă calea sub directorul cozii și validează proprietarul. Refuză orice separator, componentă părinte sau symlink.\",\"Un slot real poate fi eliberat. Probe izolate cu ../marker, cale absolută, symlink și slotul altui solicitant nu modifică fișierul martor.\"],[\"F02\",\"P1\",\"O sesiune acceptată cu puls activ poate pierde propriul container PG\",\"LEASE HR\",\"8 10\",\"În prima rulare de integrare, curățarea globală a clasificat PG drept orfan în timp ce sesiunea aprobată era în execuție; cu nume acceptat de lista de sesiuni cele 3 probe HR trec.\",\"tools/status/containere_cere.py:145 tools/status/containere_cere.py:465 tools/status/containere_cere.py:685\",\"Nume de sesiune acceptat la înregistrare, dar nerecunoscut de selecția pentru sesiuni active în context SSH fără TTY.\",\"Poate produce fals eșec de test și pierderea unei resurse sintetice active.\",\"Folosește identificatorul permisului și lease-ul cu puls ca autoritate comună pentru admitere și curățare. Solicitant necunoscut se respinge înainte de creare.\",\"Sesiunea din reproducere păstrează primul container când cere al doilea; expirarea reală rămâne demonstrabilă.\"],[\"F03\",\"P1\",\"Cheia repetată acceptă și corpul unei operații diferite\",\"RUN\",\"12\",\"Același POST partners, tenant și cheie, cu nume/CUI diferite, primește HTTP 201 și ID-ul operației precedente. Alt tenant dă un ID diferit.\",\"backend/app/idempotency.py:24 backend/app/models.py:711 backend/app/routers/partners.py:156\",\"Identitate tenant simulată conform fixturii proiectului; se reutilizează cheia pentru o cerere diferită.\",\"Operatorul vede succes pentru o solicitare ale cărei date nu au fost aplicate.\",\"Leagă cheia existentă de hashul canonic al comenzii și de criteriile necesare de context. Respinge conflictul înainte de efect și expune ID-ul operației originale.\",\"Același corp se reia, corp schimbat primește conflict, altă firmă rămâne separată.\"],[\"F04\",\"P1\",\"Căderea între succesul nativ și commitul local creează două efecte în simulator\",\"RUN\",\"13 15\",\"Prima cerere provoacă efectul 101 și eroare HTTP 500 la salvarea cheii; a doua creează 102 și mirror-ul conține numai 102.\",\"backend/app/routers/partners.py:173 backend/app/routers/partners.py:192 backend/app/idempotency.py:33\",\"Clientul nativ este un stub fără deduplicare, store eșuează după apel. Nu este probă de duplicat în producție.\",\"Reluarea poate dubla partenerul dacă documentul nativ nu dispune de o cheie stabilă de reconciliere.\",\"Rezervă identitatea operației înainte de apel și transmite referința de business care permite regăsirea PO-ului nativ. Clarifică efectul ambiguu înainte de retry.\",\"Injecții după fiecare frontieră de commit și două cereri concurente trebuie să lase un singur ID nativ și o singură asociere.\"],[\"F05\",\"P1\",\"Două revendicări ale unui job pot genera două rezultate\",\"RUN\",\"17 18\",\"Aceeași intrare Queued poate fi citită prin claim_next de două sesiuni. process_task executat pentru cele două revendicări a comis două rezultate pentru același task.\",\"backend/app/ai_assistant/worker.py:24 backend/app/ai_assistant/service.py:63\",\"În laborator SQLite, două sesiuni cu revendicări intercalate determinist. Providerul nu produce efect extern.\",\"La mai mulți lucrători pot apărea procesări și rezultate duplicate.\",\"Folosește actualizare condiționată Queued→Running cu token/lease sau blocarea nativă disponibilă în Postgres; constrângere și cheie logică pentru rezultat.\",\"Doi lucrători revendică atomic, numai unul obține tokenul. După moarte/lease expirat rămâne cel mult un efect de business.\"],[\"F06\",\"P1\",\"Jurnalul păstrează tokenii din obiectele imbricate\",\"RUN\",\"16\",\"AuditEvent maschează tokenul la nivelul principal, dar canarul din payload.token și payload.authorization se regăsește în after_json.\",\"backend/app/audit.py:10 backend/app/audit.py:23\",\"Cod care apelează record cu valori sensibile în obiect imbricat și utilizator cu acces la jurnal. Se folosesc numai canari sintetici.\",\"Secretele sau datele cu acces limitat pot persista nemascate în jurnal.\",\"Aplică filtrare recursivă la dicționare/liste și o listă de câmpuri permisă per eveniment; verifică authorization și variații de literă.\",\"Probe cu canari la nivelurile 1–3 în liste/dicționare și prin export/jurnal. Zero canari sensibili după persistare.\"],[\"F07\",\"P2\",\"Readiness-ul iDempiere declară status ok când dependența este indisponibilă\",\"RUN A05\",\"19\",\"La /internal/idempiere/health, răspunsul de probă reachable=false/ReadTimeout produce tot HTTP 200 și status ok.\",\"backend/app/routers/health.py:14 backend/app/idempiere/client.py:156\",\"Un consumator interpretează doar codul HTTP sau câmpul de nivel superior.\",\"Poate accepta trafic sau începe o operație în timp ce ERP nu este disponibil.\",\"Definește separat liveness și readiness, agregă indisponibilitatea în status și HTTP corespunzător. Verifică starea aplicației și schema funcțională.\",\"Dependency fail → stare degradată, recovery → stare disponibilă. Confirmă consumatorul real înaintea rolloutului.\"],[\"F08\",\"P2\",\"Catalogul returnează HTTP 500 la parametri de paginare invalizi\",\"LOAD\",\"26\",\"Parametrii page=abc și per_page=abc produc 500 cu corp care nu este JSON.\",\"frontend/storefront/app/factory.py:336 frontend/storefront/app/factory.py:344\",\"Cerere la ruta publică a catalogului cu intrări neîntregi.\",\"Consumatorii nu primesc motivul validării, iar monitorizarea tratează inputul ca eroare server.\",\"Validează tipul și intervalul înainte de query. Folosește răspunsul de eroare stabil al API și păstrează politica pentru valori negative.\",\"În cazul valorilor invalide întoarce 4xx JSON determinist, fără excepție server, în toate limbile/pe ambele canale.\"],[\"F09\",\"P2\",\"Catalogul sintetic cu 10.000 produse depășește pragul de laborator\",\"LOAD\",\"25\",\"Cu 10 cereri concomitente p95=3,111s vs obiectiv 2s; cu 30 p95=9,105s. Fiecare profil are 100 probe și niciun răspuns eronat.\",\"frontend/storefront/app/factory.py:336\",\"Proces Flask in-process, fixtură locală fără proxy/ERP, măsurare pe stația de audit.\",\"Latența observată afectează navigarea la volum sau concurență mare în aceeași configurație.\",\"Profilează sortarea/filtrarea și copierea catalogului per cerere. Reutilizează query cu paginare și indexare pe canal înainte de cache global.\",\"Repetă cu același set, seed și concurență, apoi pe staging cu proxy. Aprobă prag operațional cu responsabilul canalului.\"]].map(([id,severity,title,eids,nums,ob,files,pre,impact,fix,rt])=>({finding_id:'A10-'+id,severity,title,evidence_ids:eids.split(' '),control_ids:nums.split(' ').map(Number).map(short),observed_fact:ob,anchors:files.split(' ').map(k=>{const j=k.lastIndexOf(':'),file=k.slice(0,j),line=Number(k.slice(j+1)),buf=fs.readFileSync(p.join(src,file));const [CREDENTIAL_REDACTED]\\r?\\n/)[line-1];return{file,line,symbol:signature?.trim().slice(0,220),sha256:hash(buf),git_sha:repo}}),preconditions:pre,scope:pre,confidence:id==='F09'?'ridicată pentru fixture, transferabilitate în producție nestabilită':'ridicată pentru condițiile reproduse',classification:id==='F09'?'prag intern de performanță':'defect reprodus pe condițiile descrise',evidence_level:id==='F02'?'probă transversală cu reluare și jurnale':'reproducere izolată cu probă brută',impact,native_first_remediation:fix,regression_test:rt,owner:'A10',status:'DESCHIS',A11_decision:'ÎN AȘTEPTARE',false_positive_history:[],reproduction:id==='F02'?'Compară EV-OPS-LEASE-01 cu proba HR corectată; rularea originală și reluarea rămân în registru.':('Rulează scriptul fixture asociat dovezii '+eids.split(' ')[0]+' și compară valorile exacte cu observed_fact.')}));
const controls=[[\"PARTIAL\",\"VERS BUNDLE WEB\",\"Pentru toate cele cinci cabinete am citit ID-ul imaginii și SHA256 a trei JAR-uri. JAR mobil corespunde Git, JAR contabil diferă. În CESIRO, 44 clase sunt numai în artefactul Git și 32 au bytecode diferit.\",\"Validarea exactă a istoricului build/livrării pentru fiecare cabinet și ramurile UI la versiunile vechi.\"],[\"PARTIAL\",\"VERS BUNDLE NATIVE\",\"Inventarul pe cinci instanțe și comparația de clase separă binarele. Imaginea comună, JAR și versiunea core sunt diferențiate în dovezi.\",\"Echivalența OSGi/class loader pentru fiecare metodă și toate configurațiile multi-bundle.\"],[\"PARTIAL\",\"VERS NATIVE BUNDLE\",\"Există release-13, hash JAR efectiv și matrice core nativ. Clasele diferite rămân vizibile.\",\"Nu s-a dovedit versiunea sursă exactă a întregului build core din martie și toate semnăturile de business folosite de fiecare document.\"],[\"PARTIAL\",\"A05 VERS\",\"În laboratorul A05, la prima pornire tabela WMS a devenit disponibilă ulterior răspunsului inițial al serviciului.\",\"Rularea dublă AD pe două versiuni complete, întreruperea și reconcilierea duplicatelor pentru toate obiectele cerute.\"],[\"PARTIAL\",\"GUARDS SUITE BUNDLE\",\"Trei harness-uri de build/test și curățare au rulat pe exportul fixat în repo temporar, inclusiv mutant de compilare detectat. Verificările text/compile sunt separate de clasa activă instalată.\",\"Build reproductibil complet, inclusiv injectarea unei clase vechi și verificarea JAR-ului încărcat în OSGi.\"],[\"PARTIAL\",\"VERS A05 BUNDLE\",\"Cele cinci cabinete au aceeași imagine și aceleași amprente în momentul citirii. Git conține un alt JAR contab.\",\"Upgrade parțial intenționat și login/smoke pe clone distincte pentru fiecărui cabinet.\"],[\"PARTIAL\",\"QUEUE\",\"Scripturile nemodificate, în cozi clonate, admit exact 3 builduri și 6 suite. Următoarea cerere primește rc10.\",\"Caz simultan pe ultimul slot și variație sub prag de RAM în fixture.\"],[\"FAIL_DOVEDIT\",\"QUEUE LEASE\",\"Sloturile simulate se eliberează în caz nominal, dar elibereaza ../marker șterge markerul extern cozii. Mecanismul global de curățare a înlăturat altădată un PG cu sesiune autorizată activă.\",\"A11 reproduce separat validarea numelui și clasificarea sesiunii.\"],[\"FAIL_DOVEDIT\",\"QUEUE\",\"Poarta de montare din replică permite un singur slot și refuză saltul peste primul solicitant. Eliberarea acceptă totuși ../marker și șterge fișierul exterior.\",\"Nu s-au făcut montări de producție. Fereastra de transfer între două montări reale rămâne neexercitată.\"],[\"PARTIAL\",\"RESTORE VERS SUITE HR LEASE\",\"PG sintetic a primit slot și permis, a avut network=none și s-a închis. Trei teste HR trec în rețeaua internă corect asociată.\",\"Verificare exhaustivă a schedulere-lor și a montărilor tuturor sui­telor de partener.\"],[\"PARTIAL\",\"GUARDS SUITE\",\"Suite țintite au respins clasa necompilabilă și au detectat erori simulate la curățare. Trei probe HR au separat defectul de nume al sesiunii de comportamentul HR.\",\"Cei doi mutanți exacți pentru toate suitele de efecte operaționale și falsul succes UI.\"],[\"FAIL_DOVEDIT\",\"RUN SUITE\",\"Ruta POST /api/v1/partners a răspuns 201 la două corpuri diferite cu aceeași cheie și același ID. Firma B a primit alt ID în fixture. Testele native ale proiectului acoperă reluarea corpului identic.\",\"Dinamica de concurență pe PostgreSQL/PostgreSQL și toate endpointurile materiale.\"],[\"FAIL_DOVEDIT\",\"RUN\",\"După succesul în adaptorul nativ simulat și o eroare locală la idempotency.store, ruta întoarce 500. Reluarea întoarce 201, două efecte externe simulate 101 și 102, mirror numai pentru 102.\",\"Cât de des se întâmplă în instalație și ce validări aplică metoda nativă pentru toate tipurile de partener.\"],[\"PARTIAL\",\"SUITE A08\",\"Suita t22_releu include separarea cabinetelor, semnătură, necunoscut, rețea și apeluri zero către cabinet implicit. A08 a reprodus în fixture o ofertă veche care înlocuiește o versiune mai nouă.\",\"Transportul semnat prin procesul ERP, de la început la sfârșit, cu evenimente inverse și retururi.\"],[\"FAIL_DOVEDIT\",\"RUN\",\"Criza între efect nativ și registrul local este reproductibilă. Al doilea apel produce altă identitate în stub, iar primul efect nu se mai află în răspunsul final.\",\"Reconciliere documente multi-linie, înapoiere și colete reale în ERP izolat.\"],[\"FAIL_DOVEDIT\",\"RUN\",\"În AuditEvent.after_json, canarul token de la nivelul 1 este mascat. Tokenul sub payload și authorization imbricat rămân în DB în clar.\",\"Suprafața tuturor registrelor de erori, vizibilitatea prin UI și eventualul secret real din câmpurile respective.\"],[\"FAIL_DOVEDIT\",\"RUN SUITE\",\"Două sesiuni SQL au revendicat taskul A10-ONE în starea Queued. Procesarea celor două revendicări a creat două EVA_AI_Result pentru același task și starea Completed.\",\"Test cu două procese reale și sarcină LLM/OCR în Postgres.\"],[\"PARTIAL\",\"SUITE RUN\",\"Testele PSD2 înregistrate acoperă selecție/skip în interval, eligibilitate, tenant și provider. Concurența jobului AI contrazice revendicarea exclusivă.\",\"Backoff 429 Retry-After, 503 și erori definitive pe toate adaptoarele, cu aviz operator.\"],[\"FAIL_DOVEDIT\",\"RUN A05\",\"Cu clientul nativ simulat ca unreachable/ReadTimeout, /api/v1/internal/idempiere/health răspunde 200 și status ok la nivel superior. /health (liveness) separat răspunde 200.\",\"Influența acestui endpoint asupra unei sonde de deploy depinde de consumator. Nicio stare contabilă reală nu e inferată.\"],[\"PARTIAL\",\"RUN SUITE\",\"Se poate identifica același job și numărul anormal de rezultate în DB. Suita acoperă vizibilitatea bazală și progres.\",\"Alarmă operator blocat fără heartbeat, vechime restantă și recuperare în UI la volum mare.\"],[\"PARTIAL\",\"RESTORE\",\"În PG16 fără rețea am creat document sintetic 42, CO, debit/credit 18, o anexă cu SHA cunoscut. pg_dump + arhivă de fișier au amprente verificabile.\",\"Snapshot