a diferă pe trasee. A08 include un import de catalog cross-canal fără sesiune.\",\"Confirmarea exhaustivă a drepturilor și limitelor de intrare pe toate cele 117 suprafețe de responsabilitate A10.\"]].map(([s,ev,observed,lim],i)=>{const c=plan.controls[i],related=findings.filter(f=>f.control_ids.includes(c.control_id));return{control_id:c.control_id,task_ids:c.task_ids,requirement_id:c.requirement_id,pipeline_ids:c.pipeline_ids,layer:c.layer,expected:c.expected,method:c.steps_or_command,status:s,observed,limitations:lim,evidence_ids:ev.split(' '),finding_ids:related.map(f=>f.finding_id),environment:c.environment,negative_planned:c.negative_variant,actual_scope:ev.split(' ').map(id=>evidence[id].limitations),cleanup:'Resursele de laborator ale A10 apar în înregistrarea brută. SSH de inventar este read-only. Docker pentru restore are zero instanțe rămase.',executor:'A10',reviewer:'A11, în așteptare'};});
